// Question banks: aek, gases, nuclear, organic1, organic2, labdata.
// Convention: first 5 are warm-ups, the next 20 are CCC/CCO/USNCO style.
import type { QuizQ } from './framework';

export const AEK_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'aek-001', topic: 'aek', skill: 'acids/ph-calc', q: 'pH of 0.01 M HCl?', opts: ['1', '12', '2', '0.01'], a: 2, why: 'Strong acid fully dissociates: [H⁺] = 10⁻² → pH = 2.', misconception: '<b>Strong</b> and <b>concentrated</b> are unrelated words. Strong describes how <em>completely</em> an acid dissociates — a property of the substance. Concentrated describes how <em>much</em> of it is in the solution — a property of the mixture. This 0.01 M HCl is a strong acid at a low concentration. Compare 1 M acetic acid (weak but concentrated, pH 2.4) with 0.001 M HCl (strong but dilute, pH 3.0): the <em>weak</em> acid is the more acidic solution of the two. Neither word predicts the other, so never reach for "strong ⇒ low pH".' },
  { id: 'aek-002', topic: 'aek', skill: 'acids/ph-calc', q: 'At 25 °C, pH + pOH = ?', opts: ['7', '10', '1', '14'], a: 3, why: 'Kw = 10⁻¹⁴ → taking −log of [H⁺][OH⁻] = 10⁻¹⁴ gives pH + pOH = 14.' },
  { id: 'aek-003', topic: 'aek', q: 'Oxidation is the ______ of electrons.', opts: ['loss', 'gain', 'sharing', 'pairing'], a: 0, why: '"OIL RIG": Oxidation Is Loss, Reduction Is Gain.' },
  { id: 'aek-004', topic: 'aek', skill: 'acids/ph-calc', q: 'A pH of 3 compared to pH 5 is…', opts: ['2× more acidic', '100× more acidic', '2 units more basic', '10× more acidic'], a: 1, why: 'Each pH unit is a factor of 10 in [H⁺]: two units = 100×.' },
  { id: 'aek-005', topic: 'aek', q: 'Raising temperature generally makes reactions…', opts: ['slower', 'unchanged', 'faster', 'reverse'], a: 2, why: 'More molecules clear the activation-energy bar (Boltzmann tail grows exponentially).' },
  // ---- olympiad ----
  { id: 'aek-006', topic: 'aek', skill: 'acids/titration-curves', q: 'Halfway to equivalence in a weak acid–strong base titration, pH = …', opts: ['7', 'pKb', '½ pKa', 'pKa of the acid'], a: 3, why: '[HA] = [A⁻] → Henderson–Hasselbalch gives pH = pKa exactly. This is how pKa is measured.', misconception: 'Half-equivalence is where pH = pKa, and it has nothing to do with pH 7. At that point exactly half the acid has been converted, so [HA] = [A⁻] and the log term in Henderson–Hasselbalch vanishes. The <em>equivalence</em> point is a different place entirely — pH 7 only for a strong acid with a strong base, and above 7 for any weak acid.' },
  { id: 'aek-007', topic: 'aek', q: 'You multiply a half-reaction by 2. Its E°…', opts: ['is unchanged', 'halves', 'doubles', 'flips sign'], a: 0, why: 'Potential is INTENSIVE. (ΔG° = −nFE° scales instead, through n.)', misconception: 'E° is intensive: multiplying a half-reaction changes nothing about its potential. Doubling 2H⁺ + 2e⁻ → H₂ does not double 0.00 V, because potential is energy <em>per coulomb</em> and both halves of that ratio scale together. What does scale is ΔG° = −nFE°, through n — which is exactly why you combine half-reactions by adding ΔG°, not by adding E° values, whenever n differs.' , why2: 'Look at the units. A volt is a joule per coulomb — a <em>ratio</em>. Doubling the half-reaction doubles the joules released and doubles the coulombs passed, so the quotient is unchanged, exactly as heating twice as much water to the same temperature does not make it twice as hot. E° belongs with temperature, density and pressure (intensive); ΔG°, n, mass and charge scale with size (extensive). The practical consequence is worth more than the fact itself: you may never add E° values to build a new half-reaction. Convert each to ΔG° = −nFE°, add those, and divide by the new n — which is why E° for Fe³⁺/Fe is not E°(Fe³⁺/Fe²⁺) + E°(Fe²⁺/Fe).' },
  { id: 'aek-008', topic: 'aek', q: 'First-order reaction, t½ = 10 min. Fraction left after 30 min?', opts: ['1/3', '1/8', '1/6', '1/9'], a: 1, why: '3 half-lives → (½)³ = 1/8. First-order t½ never depends on concentration.' },
  { id: 'aek-009', topic: 'aek', skill: 'acids/buffers', q: 'Which mixture is a buffer?', opts: ['HCl + NaCl', 'NaOH + NaCl', 'CH₃COOH + CH₃COONa', 'HNO₃ + NaNO₃'], a: 2, why: 'A buffer needs a WEAK conjugate pair. Strong acids\' conjugates (Cl⁻, NO₃⁻) have no appetite for protons.' },
  { id: 'aek-010', topic: 'aek', q: 'The experimental rate law reflects the mechanism\'s…', opts: ['slowest step', 'fastest step', 'overall equation', 'final step'], a: 0, why: 'The rate-determining step is the bottleneck; overall coefficients only give orders for single-step (elementary) reactions.', misconception: 'Rate-law exponents come from <em>experiment</em>, never from reading the coefficients off the balanced equation. For 2NO + O₂ → 2NO₂ the balanced equation tempts you into rate = k[NO]²[O₂], and there it happens to be right — but for H₂ + Br₂ → 2HBr the measured rate law is k[H₂][Br₂]^½, which no coefficient could have told you. Only an <em>elementary</em> step lets you read orders off stoichiometry, and you can never know a step is elementary just by looking at it.' },
  { id: 'aek-011', topic: 'aek', q: 'In a galvanic cell, electrons flow…', opts: ['cathode → anode', 'cation → anion', 'through the salt bridge', 'anode → cathode'], a: 3, why: 'Oxidation at the anode releases electrons into the wire. "An Ox, Red Cat."', misconception: 'Electrons leave the anode and travel through the external wire to the cathode — they never cross the salt bridge. The salt bridge carries <em>ions</em>, and it exists to keep both compartments electrically neutral; without it the cell stops within moments even though the metals and wire are untouched. Drawing electron flow through the bridge is a mechanism that cannot work: electrons do not swim through electrolyte solutions.' },
  { id: 'aek-012', tier: 3, topic: 'aek', skill: 'acids/ph-calc', q: 'pH of 0.10 M weak acid with Ka = 1.0×10⁻⁵?', opts: ['1.0', '5.0', '3.0', '2.5'], a: 2, why: 'x ≈ √(KaC) = √(10⁻⁶) = 10⁻³ M → pH = 3.00. (x is 1% of C — approximation valid.)', misconception: 'pH = pKa holds only at half-neutralisation, not for an acid simply dissolved in water — answering 5.0 is reading pKa off the Ka and stopping there. Nor is a weak acid fully ionised: 0.10 M would only give pH 1.0 if every molecule dissociated, whereas here x = √(KaC) = 10⁻³ M, about 1% of the acid.' },
  { id: 'aek-013', topic: 'aek', skill: 'acids/strong-weak', q: 'Ka of HF is 6.8×10⁻⁴. Kb of F⁻ = ?', opts: ['6.8×10⁻⁴', '1.5×10⁻¹¹', '6.8×10⁻¹⁸', '1.5×10⁻⁴'], a: 1, why: 'Kb = Kw/Ka = 10⁻¹⁴/6.8×10⁻⁴ ≈ 1.5×10⁻¹¹. Conjugates multiply to Kw.' },
  { id: 'aek-014', topic: 'aek', skill: 'acids/strong-weak', q: 'Which 0.1 M salt solution is basic?', opts: ['NaF', 'NH₄Cl', 'NaCl', 'NaNO₃'], a: 0, why: 'F⁻ is the conjugate base of a WEAK acid (HF) → hydrolyzes: F⁻ + H₂O ⇌ HF + OH⁻. Cl⁻/NO₃⁻ are neutral spectators; NH₄⁺ is acidic.' },
  { id: 'aek-015', tier: 3, topic: 'aek', q: 'A battery is "dead" when…', opts: ['E° = 0', 'Q = 1', 'the anode dissolves fully', 'Q = K (so E = 0)'], a: 3, why: 'The cell drives toward equilibrium; at Q = K the Nernst equation gives E = 0 — no more push, even with reactants left.', misconception: 'E° is a fixed property of the cell chemistry and does not drain away with use — a dead battery still has exactly the E° it started with. What has fallen to zero is the actual E, because Q has climbed to K. "Dead" therefore means "at equilibrium", not "out of reactants": there is usually plenty of reactant left.' },
  { id: 'aek-016', topic: 'aek', q: 'Electrolysis of aqueous NaCl: the product at the CATHODE is…', opts: ['Na metal', 'Cl₂ gas', 'H₂ gas', 'O₂ gas'], a: 2, why: 'Water (−0.83 V) is far easier to reduce than Na⁺ (−2.71 V) → H₂ + OH⁻. Molten NaCl is how you get sodium metal.', misconception: 'What is reduced at a cathode is whatever is <em>easiest</em> to reduce, and in aqueous solution that is often water, not the cation on the label. Electrolysing aqueous NaCl gives H₂, not sodium, because reducing water (−0.83 V) is far easier than reducing Na⁺ (−2.71 V). Sodium metal requires <em>molten</em> NaCl, where no water is present to be reduced first.' },
  { id: 'aek-017', topic: 'aek', q: 'Charge needed to plate 0.10 mol of Ag from Ag⁺?', opts: ['96485 C', '9650 C', '4825 C', '19300 C'], a: 1, why: 'n = 1 e⁻ per Ag: Q = 0.10 × 96485 ≈ 9650 C (≈ 2.7 A·h).' },
  { id: 'aek-018', topic: 'aek', q: 'Doubling [A] quadruples the initial rate. Order in A?', opts: ['2', '1', '0', '3'], a: 0, why: 'rate ∝ [A]ⁿ: 2ⁿ = 4 → n = 2. Method of initial rates in one line.' },
  { id: 'aek-019', topic: 'aek', q: 'A catalyst speeds a reaction by…', opts: ['raising the temperature', 'increasing collision frequency', 'shifting the equilibrium right', 'lowering Ea for forward AND reverse'], a: 3, why: 'A new pathway with lower barrier — both directions accelerate equally, so K and ΔG° are untouched.', misconception: 'A catalyst changes the <em>time</em> to reach equilibrium, never the <em>yield</em> at equilibrium. Because it lowers the barrier equally in both directions, kf and kr rise by the same factor and K = kf/kr is unchanged — as is ΔG°, which is fixed by the reactants and products alone and knows nothing about the path between them.' },
  { id: 'aek-020', topic: 'aek', q: 'For a SECOND-order reaction, the half-life…', opts: ['is constant', 'is zero', 'gets shorter as it proceeds', 'gets longer as the reaction proceeds'], a: 3, why: 't½ = 1/(k[A]₀): as [A] falls, each successive half-life doubles — the long tail of 2nd-order decays.', misconception: 'A constant half-life is a property of first-order kinetics alone, not of decay in general. For a second-order reaction t½ = 1/(k[A]₀), so every successive half-life is twice as long as the last, and the reaction develops a very long tail. If a question gives you a half-life and expects it to be constant, it has told you the order — and if the half-life is drifting, that is your evidence the reaction is not first order.' },
  { id: 'aek-021', tier: 3, topic: 'aek', skill: 'acids/polyprotic', q: 'In the titration of H₂CO₃ (diprotic) with NaOH, the pH at the FIRST half-equivalence equals…', opts: ['pKa1', 'pKa2', '(pKa1+pKa2)/2', '7'], a: 0, why: 'The first buffer region is H₂CO₃/HCO₃⁻ → pH = pKa1 (6.35). Midway between the two equivalence points pH ≈ (pKa1+pKa2)/2.', misconception: 'Each proton of a diprotic acid has its own half-equivalence AND its own equivalence point, and the two are easily slid into one another. The first half-equivalence sits in the H₂CO₃/HCO₃⁻ buffer, so pH = pKa1; the average (pKa1 + pKa2)/2 belongs to the first EQUIVALENCE point, where amphiprotic HCO₃⁻ is the only species present. Picking the average means shifting one step along the curve.' },
  { id: 'aek-022', tier: 3, topic: 'aek', skill: ['acids/indicators', 'acids/titration-curves'], q: 'The best indicator for a titration has pKind close to…', opts: ['7 always', 'the pH at the equivalence point', 'the pKa of the analyte acid', '0'], a: 1, why: 'The indicator flips within pKind ± 1 — that window must straddle the steep jump at equivalence (8.7 for weak acid/strong base → phenolphthalein).', misconception: 'The indicator must flip where the curve is STEEP, which is the equivalence point — not pH 7, and not the analyte\'s pKa, which marks half-equivalence in the flattest part of the buffer region. Only strong acid with strong base has its equivalence at 7; a weak acid titrated with strong base leaves a basic salt and jumps through about 8.7, which is why phenolphthalein works there and methyl orange does not.' },
  { id: 'aek-023', topic: 'aek', q: 'The strongest OXIDIZING agent here is…', opts: ['Li⁺ (E° = −3.04 V)', 'Zn²⁺ (−0.76 V)', 'F₂ (+2.87 V)', 'Cu²⁺ (+0.34 V)'], a: 2, why: 'Most positive reduction potential = most eager to be reduced = strongest oxidizer. (Li METAL is the strongest reducer — flip sides!)', misconception: 'A standard reduction potential table ranks oxidising strength <em>as written</em> — as reductions. The most positive E° is the best oxidising agent (F₂ at +2.87 V), and the most negative marks the best reducing agent, but that reducing agent is the <em>metal</em> on the right-hand side, not the ion on the left. Li⁺ is a terrible oxidiser; Li metal is a superb reducer. Read which side of the half-equation the species you are asked about is on.' },
  { id: 'aek-024', topic: 'aek', q: 'A species produced in one mechanism step and consumed in a later one is a(n)…', opts: ['catalyst', 'activated complex', 'inhibitor', 'intermediate'], a: 3, why: 'Intermediates appear AFTER they\'re made and vanish; catalysts enter FIRST and are regenerated. Neither may appear in the overall equation.' },
  { id: 'aek-025', topic: 'aek', q: 'ln k vs 1/T is a straight line with slope equal to…', opts: ['−Ea/R', 'Ea', '−Ea', 'A (frequency factor)'], a: 0, why: 'Arrhenius linearized: ln k = ln A − (Ea/R)(1/T). Steeper slope = bigger Ea = more temperature-sensitive.' },
];

export const GASES_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'gas-001', topic: 'gases', q: 'STP temperature is…', opts: ['0 °C', '25 °C', '100 °C', '−273 °C'], a: 0, why: '0 °C (273.15 K) and 1 bar. "Room temperature" 25 °C is standard-STATE, a different convention.' },
  { id: 'gas-002', topic: 'gases', skill: 'states/gas-laws', q: 'At constant T, halving the volume of a gas makes the pressure…', opts: ['half', 'double', 'unchanged', 'quadruple'], a: 1, why: 'Boyle\'s law: PV = constant.' },
  { id: 'gas-003', topic: 'gases', q: 'Absolute zero is…', opts: ['0.0 °C', '−100 °C', '−273.15 °C', '−373 °C'], a: 2, why: '0 K — where ideal-gas volume extrapolates to zero and molecular motion is minimal.' },
  { id: 'gas-004', topic: 'gases', skill: 'states/kmt', q: 'Kinetic molecular theory assumes gas particles…', opts: ['attract one another strongly', 'all travel at the very same speed', 'move slowly and steadily', 'have no volume and no attractions'], a: 3, why: 'Point particles, elastic collisions, no IMFs — the assumptions that break down at high P and low T.', misconception: 'The kinetic model does not assume all particles move at the same speed — it assumes the <em>opposite</em>, and that is the whole point of the Maxwell–Boltzmann distribution. At any instant the sample contains a huge spread of speeds, and temperature fixes the shape of that spread rather than a single value. The real assumptions are point-like particles, no intermolecular forces and perfectly elastic collisions, all three of which fail at high pressure and low temperature.' },
  { id: 'gas-005', topic: 'gases', skill: 'states/imf', q: 'The strongest intermolecular force in liquid water is…', opts: ['hydrogen bonds', 'permanent dipole–dipole', 'London dispersion forces', 'ionic attraction'], a: 0, why: 'O–H donors + O lone pairs = up to 4 H-bonds per molecule — the source of water\'s weird properties.' },
  // ---- olympiad ----
  { id: 'gas-006', topic: 'gases', skill: 'states/kmt', q: 'He effuses how many times faster than CH₄ (M = 16)?', opts: ['4×', '2×', '√2×', '16×'], a: 1, why: 'Graham: rate ∝ 1/√M → √(16/4) = 2.' },
  { id: 'gas-007', topic: 'gases', skill: 'states/real-gases', q: 'A real gas behaves most ideally at…', opts: ['low T, high P', 'low T, low P', 'high T, low P', 'high T, high P'], a: 2, why: 'Kinetic energy swamps attractions (high T); molecular volume is negligible (low P).', misconception: 'Ideality is favoured by high temperature and LOW pressure, which is the opposite of the intuitive answer. High pressure pushes molecules close enough that their own volume matters (the b term), and low temperature lets attractions bite (the a term). "High T, high P" gets half the reasoning right and the other half exactly backwards.' },
  { id: 'gas-008', topic: 'gases', skill: 'states/imf', q: 'Which noble gas has the highest boiling point?', opts: ['He', 'Ne', 'Ar', 'Xe'], a: 3, why: 'Dispersion forces grow with polarizability (electron count): Xe 165 K ≫ He 4 K.' },
  { id: 'gas-009', topic: 'gases', skill: 'states/gas-laws', q: 'H₂ collected over water at 25 °C, total P = 770 torr, P°(H₂O) = 24 torr. P(H₂) = ?', opts: ['746 torr', '794 torr', '770 torr', '386 torr'], a: 0, why: 'Dalton: subtract the water vapor. 770 − 24 = 746 torr — skip this and your mole count is inflated.' },
  { id: 'gas-010', topic: 'gases', skill: 'states/phase-behaviour', q: 'Water\'s solid–liquid line slopes LEFT (negative). Therefore…', opts: ['ice sublimes easily', 'water can\'t freeze under pressure', 'pressure melts ice', 'ice is denser than water'], a: 2, why: 'Compressing at constant T crosses solid → liquid because ice is LESS dense. Nearly unique to water.', misconception: 'Water\'s solid–liquid line slopes backwards because ice is <em>less</em> dense than liquid water — nearly every other substance slopes the normal way. That negative slope means increasing the pressure at constant temperature melts ice rather than freezing water. Assuming solid is always denser than liquid works for almost everything and fails for exactly the substance every exam asks about.' },
  { id: 'gas-011', topic: 'gases', skill: 'states/gas-laws', q: 'Density of CO₂ (M = 44) at 0 °C and 1 atm ≈ ?', opts: ['1.00 g/L', '1.96 g/L', '0.5 g/L', '44 g/L'], a: 1, why: 'd = PM/RT = M/22.4 ≈ 1.96 g/L — heavier than air (29 g/mol effective), which is why CO₂ pools low.' },
  { id: 'gas-012', topic: 'gases', skill: 'states/kmt', q: 'To DOUBLE the rms speed of a gas sample, its Kelvin temperature must…', opts: ['quadruple', 'double', 'increase √2×', 'increase 8×'], a: 0, why: 'v(rms) ∝ √T → doubling speed needs 4× the absolute temperature.', misconception: 'Root-mean-square speed goes as √T, not T, so speeds and temperatures do not scale together. Doubling v_rms needs FOUR times the absolute temperature; it is the average kinetic energy (½mv²) that is proportional to T. And the temperature must be in kelvin — doubling 300 °C is meaningless here.' },
  { id: 'gas-013', topic: 'gases', skill: 'states/gas-laws', q: 'A flask holds 1 mol N₂ and 3 mol H₂ at 8 atm total. P(N₂) = ?', opts: ['1 atm', '6 atm', '4 atm', '2 atm'], a: 3, why: 'Mole fraction ¼ × 8 atm = 2 atm. Partial pressure = xᵢ·P(total).' },
  { id: 'gas-014', topic: 'gases', skill: 'states/real-gases', q: 'In van der Waals, a LARGE "a" constant means the gas…', opts: ['has large, bulky molecules', 'is monatomic, like argon', 'has strong attractions', 'behaves almost ideally'], a: 2, why: '"a" corrects pressure for attractions (P is lower than ideal). NH₃ and H₂O have big a; He tiny. "b" is molecular volume.' },
  { id: 'gas-015', topic: 'gases', skill: 'states/phase-behaviour', q: 'Half the liquid in a sealed flask is removed (some liquid remains). The vapor pressure…', opts: ['halves', 'is unchanged', 'doubles', 'drops to zero'], a: 1, why: 'Vapor pressure is an equilibrium property of the LIQUID at that temperature — independent of amounts, as long as liquid is present.', misconception: 'Vapour pressure is a property of the liquid at a given temperature, not of how much liquid there is. Remove half the liquid and the equilibrium simply re-establishes at the same pressure, provided <em>some</em> liquid remains; the same is true if you change the container\'s size. What does change vapour pressure is temperature, and nothing else.' , why2: 'Think of two rates at the surface, not of an amount. Molecules escape the liquid at a rate set by temperature alone (how many have enough energy to break free per unit area per second), and return at a rate proportional to how crowded the vapour is. Vapour pressure is simply where those two rates balance — and neither one knows how deep the liquid underneath is. Remove half the liquid and the headspace grows, so a little more liquid evaporates to refill it, and the pressure settles back to precisely the same value. The only way to change it is to change T (or the liquid). The argument fails at exactly one point: when the last drop evaporates there is no liquid to balance against, and what is left is just a fixed quantity of gas obeying PV = nRT.' },
  { id: 'gas-016', topic: 'gases', skill: 'states/phase-behaviour', q: 'Water boils at ~70 °C on a high mountain because…', opts: ['the atmospheric pressure is lower', 'the air is colder at altitude', 'the water is purer up there', 'weaker gravity lowers water\'s vapour pressure'], a: 0, why: 'Boiling = vapor pressure reaches external pressure. At 0.33 atm that happens at ~71 °C — food cooks slower.' },
  { id: 'gas-017', topic: 'gases', skill: 'states/colligative', q: 'Solvent mole fraction 0.90, pure vapor pressure 100 torr. Solution vapor pressure (Raoult)?', opts: ['100 torr', '81 torr', '10 torr', '90 torr'], a: 3, why: 'P = x(solvent)·P° = 0.90 × 100 = 90 torr — nonvolatile solute dilutes the surface.' },
  { id: 'gas-018', topic: 'gases', skill: 'states/real-gases', q: 'Which gas deviates MOST from ideal behavior?', opts: ['He gas', 'H₂ gas', 'NH₃', 'Ne gas'], a: 2, why: 'NH₃ hydrogen-bonds (big a) and is comparatively large (b). Small nonpolar He/H₂/Ne are the most ideal gases known.' },
  { id: 'gas-019', tier: 3, topic: 'gases', skill: 'states/colligative', q: 'Which freezes at the LOWEST temperature? (aqueous, per kg water)', opts: ['0.10 mol glucose', '0.08 mol CaCl₂', '0.10 mol NaCl', '0.15 mol sucrose'], a: 1, why: 'Count effective particles (i × m): glucose 0.10, NaCl 0.10×2 = 0.20, CaCl₂ 0.08×3 = <b>0.24</b>, sucrose 0.15. Colligative properties only count particles — CaCl₂ wins despite the smallest mole number.', misconception: 'Colligative properties count dissolved <em>particles</em>, not formula units — so the van\'t Hoff factor i has to go in before you compare. 0.08 mol of CaCl₂ releases 0.24 mol of ions and depresses the freezing point more than 0.10 mol of NaCl (0.20) or 0.15 mol of sucrose (0.15), despite having the smallest mole count on the list. Comparing molalities without multiplying by i is the standard error here.' },
  { id: 'gas-020', topic: 'gases', q: 'Warm soda goes flat faster because gas solubility…', opts: ['rises with temperature', 'falls with temperature', 'is pressure-independent', 'depends on the bottle'], a: 1, why: 'Dissolving gas is exothermic → Le Chatelier: heat pushes CO₂ out. (Henry\'s law covers the pressure half of the story.)' },
  { id: 'gas-021', topic: 'gases', skill: 'states/colligative', q: 'In osmosis, solvent flows through the membrane toward the side with…', opts: ['the lower solute concentration', 'the higher temperature side', 'higher solute concentration', 'the lower pressure side'], a: 2, why: 'Toward the more concentrated solution — diluting it. Stopping that flow takes π = iMRT of applied pressure.', misconception: 'Osmosis moves <em>solvent</em> toward the more concentrated solution, which feels backwards until you stop thinking of it as the solute moving. The membrane blocks solute entirely; solvent simply crosses more often in the direction that dilutes, because there is more free solvent on the dilute side. Describing osmosis as "solute flowing to even things out" is the model to discard — that is diffusion, and the membrane forbids it.' },
  { id: 'gas-022', tier: 3, topic: 'gases', skill: 'states/kmt', q: 'An unknown gas takes twice as long as He to effuse. Its molar mass ≈ ?', opts: ['8 g/mol', '32 g/mol', '2 g/mol', '16 g/mol'], a: 3, why: 'time ∝ √M: 2× slower → M = 4 × 2² = 16 g/mol (methane?).', misconception: 'Graham\'s law is about RATES, and time is the reciprocal of rate — twice as long means half as fast, so √(M/4) = 2 and M = 16. Multiplying the molar mass by the time ratio without squaring gives 8; forgetting to invert, and reading "twice as long" as twice as fast, sends the unknown lighter than helium instead of heavier.' },
  { id: 'gas-023', topic: 'gases', skill: 'states/phase-behaviour', q: 'Above the critical point, a substance is…', opts: ['a supercritical fluid', 'a superheated liquid phase', 'an ionised plasma', 'invariably a solid'], a: 0, why: 'Beyond Tc, Pc no pressure can condense it — density varies continuously. Supercritical CO₂ extracts caffeine.' },
  { id: 'gas-024', topic: 'gases', skill: 'states/phase-behaviour', q: 'At its triple point, a substance…', opts: ['is on the point of decomposing', 'has three phases at equilibrium', 'boils and freezes in alternation', 'is already supercritical'], a: 1, why: 'One unique (T, P) where solid, liquid, and vapor coexist — water: 0.01 °C, 0.006 atm (used to define the kelvin).' },
  { id: 'gas-025', tier: 3, topic: 'gases', skill: 'states/colligative', q: '6.0 g of an unknown nonelectrolyte in 100 g water freezes at −0.93 °C (Kf = 1.86). Molar mass ≈ ?', opts: ['60 g/mol', '180 g/mol', '120 g/mol', '30 g/mol'], a: 2, why: 'm = 0.93/1.86 = 0.50 mol/kg → 0.050 mol in 0.100 kg → M = 6.0/0.050 = <b>120 g/mol</b>. Colligative properties weigh molecules.', misconception: 'Molality is moles per kilogram of SOLVENT, so 0.50 mol/kg must still be multiplied by the 0.100 kg of water to give 0.050 mol — treating the molality as the number of moles is what shrinks the answer. The other reliable slip is inverting the first step: m = ΔT/Kf, not Kf/ΔT, which would turn 0.50 mol/kg into 2.0 and the molar mass into 30.' },
];

export const NUCLEAR_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'nuc-001', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'An alpha particle is…', opts: ['a fast-moving electron', 'a free neutron', 'a high-energy photon', 'a helium nucleus'], a: 3, why: '⁴₂He²⁺ — two protons, two neutrons. Heavy and doubly charged: stopped by paper, devastating if inhaled.' },
  { id: 'nuc-002', topic: 'nuclear', skill: 'descriptive/nuclear', q: '100 g of isotope, one half-life passes. Remaining?', opts: ['0 g', '25 g', '50 g', '75 g'], a: 2, why: 'Half decays each half-life: 100 → 50 g.' },
  { id: 'nuc-003', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'Most penetrating radiation?', opts: ['alpha', 'gamma', 'beta', 'all equal'], a: 1, why: 'γ photons carry no charge or mass — need thick lead/concrete. α stops at paper, β at aluminum foil.' },
  { id: 'nuc-004', topic: 'nuclear', skill: 'descriptive/coordination', q: 'A ligand bonds to a metal ion by donating…', opts: ['a lone pair of electrons', 'a proton to the metal', 'a neutron to the nucleus', 'positive charge to the metal'], a: 0, why: 'Ligands are Lewis bases; the metal ion is the Lewis acid. Coordinate (dative) bonding.' },
  { id: 'nuc-005', topic: 'nuclear', skill: 'descriptive/coordination', q: 'Coordination number of Co in [Co(NH₃)₆]³⁺?', opts: ['3', '4', '12', '6'], a: 3, why: 'Six NH₃ ligands bond directly to the metal → CN = 6, octahedral.' },
  // ---- olympiad ----
  { id: 'nuc-006', topic: 'nuclear', skill: 'descriptive/nuclear', q: '²³⁸U undergoes alpha decay. The daughter is…', opts: ['²³⁴Pa (Z=91)', '²³⁸Np (Z=93)', '²³⁴Th (Z=90)', '²³⁶U (Z=92)'], a: 2, why: 'A drops 4 (238→234), Z drops 2 (92→90) → thorium-234.' },
  { id: 'nuc-007', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'After 3 half-lives, percent remaining = ?', opts: ['33%', '12.5%', '25%', '6.25%'], a: 1, why: 'Each half-life halves the amount: (½)³ = 1/8 = 12.5%. Radioactive decay is strictly first-order, so the fraction depends only on the number of half-lives elapsed.', misconception: 'Half-lives do not add to a fraction — they multiply. Three half-lives leave (½)³ = 12.5%, not 3 × 50% = 150% gone or "a third left". The same trap in reverse produces "33%": the number of half-lives is an exponent, never a divisor.' },
  { id: 'nuc-008', tier: 3, topic: 'nuclear', skill: 'descriptive/coordination', q: 'In [Fe(CN)₆]³⁻, iron\'s oxidation state and d-count are…', opts: ['+3, d⁵', '+2, d⁶', '+3, d⁶', '+2, d⁵'], a: 0, why: 'Six CN⁻ = −6, overall −3 → Fe³⁺ = [Ar]3d⁵. Strong-field CN⁻ → low spin, 1 unpaired.', misconception: 'CN⁻ is an anionic ligand, so six of them contribute −6 and an overall −3 forces iron to +3 — defaulting to the more familiar Fe(II) is the first slip. The second is counting d electrons from the atom rather than the ion: Fe³⁺ has no 4s electrons at all, so it is [Ar]3d⁵, and "group 8 so d⁶" quietly keeps an electron that ionisation already removed.' },
  { id: 'nuc-009', topic: 'nuclear', skill: 'descriptive/crystal-field', q: 'Which aqueous ion is COLORLESS?', opts: ['Cu²⁺', 'Ni²⁺', 'Fe³⁺', 'Zn²⁺'], a: 3, why: 'Zn²⁺ is d¹⁰ — full d shell, no d→d transition. Same for d⁰ (Sc³⁺, Ti⁴⁺).', misconception: 'Colour in a transition-metal ion needs a partly filled d subshell for a d–d transition to be possible. Zn²⁺ is d¹⁰ — completely full, no vacancy to promote into — so it is colourless, as are d⁰ ions like Sc³⁺ and Ti⁴⁺. "It is a transition metal, so it must be coloured" fails at both ends of the row.' },
  { id: 'nuc-010', topic: 'nuclear', skill: 'descriptive/coordination', q: 'The chelate effect is driven mainly by…', opts: ['stronger M–N bonds', 'entropy, from freed water', 'solvation enthalpy', 'ligand size'], a: 1, why: 'en displacing two NH₃ increases free-particle count → ΔS > 0. Bond enthalpies are nearly identical.', misconception: 'The chelate effect is overwhelmingly <em>entropic</em>, not a matter of stronger bonds. Ethylenediamine and two ammonias form M–N bonds of essentially identical strength; what differs is that one bidentate ligand displaces two monodentate ones, so the number of free particles in solution rises and ΔS is positive. Attributing the effect to bond strength misses the mechanism and the mark.' },
  { id: 'nuc-011', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'A neutron-rich nucleus (above the belt) most likely decays by…', opts: ['alpha', 'positron emission', 'beta-minus', 'electron capture'], a: 2, why: 'β⁻ turns n → p, moving toward the belt. Proton-rich nuclei go the other way (β⁺/EC).', misconception: 'Beta-minus decay does not throw away a neutron; it <em>converts</em> one into a proton, raising Z by one while A stays put. A nucleus above the band of stability has too many neutrons, so β⁻ is what moves it back toward the band. Proton-rich nuclei do the reverse via β⁺ or electron capture — the position relative to the band, not the mass, tells you which mode to expect.' },
  { id: 'nuc-012', topic: 'nuclear', skill: 'descriptive/nuclear', q: '¹¹C (proton-rich) decays by positron emission to…', opts: ['¹²C', '¹¹N', '¹⁰B', '¹¹B'], a: 3, why: 'β⁺: p → n, Z drops 6 → 5, A stays 11 → boron-11. PET scans run on this decay.' },
  { id: 'nuc-013', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'A bone sample has 25% of its original ¹⁴C (t½ = 5730 y). Age?', opts: ['11,460 y', '5,730 y', '17,190 y', '2,865 y'], a: 0, why: '25% = two half-lives = 11,460 years.' },
  { id: 'nuc-014', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'Energy is released by fusion of light nuclei AND fission of heavy ones because binding energy per nucleon peaks at…', opts: ['helium-4', 'iron-56', 'carbon-12', 'uranium-238'], a: 1, why: 'Fe-56 tops the curve — moving toward it from either side releases energy. Stars die at iron.' },
  { id: 'nuc-015', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'Nuclear decay rates are unaffected by temperature because…', opts: ['nuclei are far too small to heat', 'the decay is zero-order, so the rate never falls off', 'the nucleus ignores chemical energies', 'emitted neutrinos carry the heat away'], a: 2, why: 'Chemical energies are eV-scale; nuclear transitions are MeV-scale (10⁶×). No Arrhenius behavior — t½ is bulletproof.', misconception: 'Nuclear half-lives are unaffected by temperature, and no Arrhenius reasoning applies to them; the one real exception, electron capture, shifts by under a percent between chemical forms of ⁷Be. Chemical processes involve electron-volt energies; nuclear transitions involve millions of electron-volts, so ordinary heating is not even remotely enough to perturb them. This immunity is what makes radiometric dating trustworthy — the clock cannot be sped up by burying, burning or dissolving the sample.' },
  { id: 'nuc-016', topic: 'nuclear', skill: 'descriptive/crystal-field', q: '[CoCl₄]²⁻ is tetrahedral and high spin because…', opts: ['Cl⁻ is a strong-field ligand here', 'tetrahedral fields produce no splitting at all', 'Co²⁺ has a filled d¹⁰ shell', 'Δt is small, so pairing never pays'], a: 3, why: 'Small Δt (fewer ligands, off-axis) < pairing energy in essentially every case → tetrahedral complexes are virtually always high spin.', misconception: 'Tetrahedral complexes are essentially always high spin, whatever the ligand. Only four ligands approach, and they do so <em>between</em> the axes, so the splitting Δt is about 4/9 of the octahedral Δo — smaller than the pairing energy in practically every case. Applying the spectrochemical series to a tetrahedral complex as though it might go low spin is the trap; the series decides Δ, but Δt starts too small for it to matter.' },
  { id: 'nuc-017', tier: 3, topic: 'nuclear', skill: 'descriptive/crystal-field', q: 'Unpaired electrons: [Fe(H₂O)₆]³⁺ vs [Fe(CN)₆]³⁻?', opts: ['5 and 1', '1 and 5', '5 and 5', '0 and 5'], a: 0, why: 'Both d⁵. Weak-field H₂O → high spin (5 unpaired); strong-field CN⁻ → low spin t₂g⁵ (1 unpaired). Measured by magnetism!', misconception: 'The spectrochemical series runs against the intuition that water, being the everyday ligand, must split strongly: H₂O is at the WEAK-field end (high spin, 5 unpaired) and CN⁻ near the strong-field end (low spin t₂g⁵, 1 unpaired). Swapping the two gives exactly the "1 and 5" answer, and the same reversal misassigns high and low spin across the whole d-block.' , why2: 'Both ions are d⁵, so there is only one decision to make: does electron number four go into the upper e<sub>g</sub> set, or pair up in t<sub>2g</sub>? That is a straight cost comparison — the splitting Δ<sub>o</sub> against the pairing energy P. H₂O sits low in the spectrochemical series (Δ<sub>o</sub> &lt; P: cheaper to climb, so the electrons spread out, <b>5 unpaired</b>); CN⁻ sits at the very top (Δ<sub>o</sub> &gt; P: cheaper to pair, so t<sub>2g</sub>⁵, <b>1 unpaired</b>). This is not a bookkeeping convention, it is measured: the magnetic moments come out near 5.9 BM and 2 BM respectively, and the strong-field cyanide complex is the intensely coloured one.' },
  { id: 'nuc-018', tier: 3, topic: 'nuclear', skill: 'descriptive/crystal-field', q: 'A complex looks yellow. It absorbs mainly…', opts: ['yellow light, which it re-emits', 'violet/blue light', 'red light at the far end', 'green, its complement'], a: 1, why: 'You see the COMPLEMENT of what\'s absorbed. Yellow appearance = violet absorbed = large Δ (strong-field ligand).', misconception: 'The colour you see is the <em>complement</em> of the colour absorbed, so a yellow complex is absorbing violet-blue light near 410–430 nm. Reading the observed colour directly as the absorbed wavelength inverts the whole argument, and it flips the conclusion about Δ: absorbing high-energy violet means a LARGE splitting and a strong-field ligand, while a red-looking complex absorbing green has a small one.' },
  { id: 'nuc-019', topic: 'nuclear', skill: 'descriptive/coordination', q: 'One EDTA⁴⁻ replaces how many water ligands on a metal ion?', opts: ['2', '4', '6', '1'], a: 2, why: 'Hexadentate: 2 N + 4 carboxylate O donors wrap the whole octahedron. 1 particle in, 6 out → huge ΔS → K(f) ~10²⁰.' },
  { id: 'nuc-020', tier: 3, topic: 'nuclear', skill: 'descriptive/coordination', q: 'How many isomers of octahedral [Co(NH₃)₄Cl₂]⁺ exist?', opts: ['1, only one arrangement', '3, counting the mirror image', '2, cis and trans', '4, one per Cl position'], a: 2, why: 'MA₄B₂: the two Cl can be adjacent (cis, 90°) or opposite (trans, 180°). Famously different colors — violet vs green.', misconception: 'cis-MA₄B₂ has a mirror plane, so there is no enantiomer to add to the count — octahedral chirality needs something like cis-M(AA)₂B₂ or M(AA)₃. Nor are the six vertices six distinct choices: the octahedron\'s symmetry means only the Cl–Cl relationship matters, 90° or 180°, which is why "one isomer per position" overcounts.' },
  { id: 'nuc-021', topic: 'nuclear', skill: 'descriptive/coordination', q: 'Oxidation state of Cr in [Cr(NH₃)₄Cl₂]⁺?', opts: ['+1', '+3', '+2', '0'], a: 1, why: 'NH₃ neutral, 2 Cl⁻ = −2, overall +1 → Cr = +3 (the most stable Cr state, d³).' },
  { id: 'nuc-022', topic: 'nuclear', skill: 'descriptive/coordination', q: '[CoBr(NH₃)₅]SO₄ and [CoSO₄(NH₃)₅]Br are…', opts: ['ionisation isomers', 'linkage isomers of sulfate', 'enantiomers of one another', 'identical compounds'], a: 0, why: 'Swap which anion is INSIDE the coordination sphere vs outside. Distinguish with AgNO₃/BaCl₂ precipitation tests.' },
  { id: 'nuc-023', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'Even-even nuclei (even Z, even N) are the most numerous stable nuclei because…', opts: ['they are the heaviest nuclides', 'they have no net nuclear spin', 'they are the most resistant to fission', 'nucleon pairing adds stability'], a: 3, why: 'Nucleons pair like electrons do: ~160 stable even-even nuclides vs only ~5 odd-odd. Magic numbers (2,8,20,28,50,82,126) stack on top.' },
  { id: 'nuc-024', topic: 'nuclear', skill: 'descriptive/nuclear', q: 'The mass of a helium-4 nucleus is LESS than 2p + 2n separately. The difference is…', opts: ['error in the measurement', 'the mass of two electrons', 'binding energy, E = Δmc²', 'the mass carried by neutrinos'], a: 2, why: 'The mass defect Δm was released as ~28 MeV of binding energy when the nucleus formed — millions of times any chemical bond.', misconception: 'The mass defect is not experimental error and not the mass of anything left over — it is binding energy, converted through E = Δmc². Assembling ⁴He from two protons and two neutrons releases about 28 MeV, and that energy leaves as mass. This is why a bound nucleus is always lighter than its separated parts, and why the biggest defect per nucleon (iron-56) marks the most stable nucleus.' },
  { id: 'nuc-025', topic: 'nuclear', skill: 'descriptive/crystal-field', q: 'Which is the correct spectrochemical trend (weak → strong field)?', opts: ['CN⁻ < H₂O < Cl⁻ < NH₃ < en', 'Cl⁻ < H₂O < NH₃ < CN⁻', 'NH₃ < Cl⁻ < CN⁻', 'H₂O < Cl⁻ < en'], a: 1, why: 'I⁻ < Br⁻ < Cl⁻ < F⁻ < OH⁻ < H₂O < NH₃ < en < NO₂⁻ < CN⁻ ≈ CO. Halides weak, C-donors strong.' },
];

export const ORGANIC1_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'og1-001', topic: 'organic1', q: 'General formula of alkanes?', opts: ['CₙH₂ₙ₊₂', 'CₙH₂ₙ', 'CₙH₂ₙ₋₂', 'CₙHₙ'], a: 0, why: 'Saturated, acyclic: every ring or π bond removes 2 H (degrees of unsaturation).' },
  { id: 'og1-002', topic: 'organic1', skill: 'organic/nomenclature', q: 'The functional group of alcohols is…', opts: ['–COOH', '–OH', '–NH₂', '–CHO'], a: 1, why: 'Hydroxyl. –COOH is carboxylic acid, –NH₂ amine, –CHO aldehyde.' },
  { id: 'og1-003', topic: 'organic1', q: 'Bond angle at an sp³ carbon?', opts: ['90.0°', '120°', '109.5°', '180.0°'], a: 2, why: 'Tetrahedral geometry — methane\'s angle.' },
  { id: 'og1-004', topic: 'organic1', q: 'Compounds with the same formula but different structures are…', opts: ['isotopes', 'polymers', 'allotropes', 'isomers'], a: 3, why: 'Isomers: constitutional (different connectivity) or stereoisomers (same connectivity, different 3D).' },
  { id: 'og1-005', topic: 'organic1', skill: 'organic/nomenclature', q: 'An alkene must contain…', opts: ['a C=C bond', 'a C≡C triple bond', 'an –OH group', 'a benzene ring somewhere'], a: 0, why: 'C=C is the defining feature; alkynes have C≡C.' },
  // ---- olympiad ----
  { id: 'og1-006', tier: 3, topic: 'organic1', skill: 'organic/substitution-elimination', q: '(CH₃)₃C–Br in warm ethanol (no added base) reacts mainly by…', opts: ['SN2', 'SN1 (+E1)', 'E2', 'no reaction'], a: 1, why: '3° blocks SN2; weak nucleophile can\'t force anything → ionization to the 3° cation (solvolysis), more E1 with heat.', misconception: 'Substrate class decides mechanism before any reagent does. A tertiary halide cannot do SN2 at all — the backside approach is physically blocked — so with a weak nucleophile like warm ethanol it ionises instead, giving SN1 with E1 alongside. "Stronger nucleophile, faster SN2" only applies where SN2 is possible in the first place; on a 3° centre it is not.' },
  { id: 'og1-007', topic: 'organic1', q: 'Strongest acid?', opts: ['ethanol, pKa 16.0', 'phenol, pKa 10.0', 'acetic acid, 4.8', 'water, pKa 15.7'], a: 2, why: 'Carboxylate delocalizes charge over two equivalent oxygens — better than phenoxide\'s ring, far better than alkoxide.' },
  { id: 'og1-008', topic: 'organic1', skill: 'organic/mechanisms', q: 'Most stable carbocation?', opts: ['CH₃⁺, methyl', 'CH₃CH₂⁺, primary', 'CH₂=CH⁺, vinyl cation', '(CH₃)₃C⁺, 3°'], a: 3, why: 'Three alkyl donors (hyperconjugation + induction). A simple vinyl cation is worse than any alkyl cation except methyl.', misconception: 'Carbocation stability is not simply "more atoms attached". It comes from electron donation into the empty p orbital by hyperconjugation and resonance, so 3° &gt; 2° &gt; 1° &gt; methyl — and a simple vinyl cation sits below every alkyl cation except methyl, because the positive charge lands on an sp carbon that holds its electrons too tightly to share. They are still real intermediates — acid-catalysed alkyne hydration and vinyl triflate solvolysis both go through one — so the rule is that they are hard to form, not that they never occur.' },
  { id: 'og1-009', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'SN2 on an (R) stereocenter gives…', opts: ['inversion', 'retention', 'racemization', 'elimination'], a: 0, why: 'Backside attack flips the umbrella (Walden inversion). Racemization is SN1\'s signature.', misconception: 'SN2 gives clean <em>inversion</em>, not racemisation — the nucleophile attacks the face opposite the leaving group and the centre turns inside out. Racemisation is the fingerprint of SN1, where a planar carbocation can be attacked from either side. Note also that inversion of configuration does not always mean the R/S label flips: that depends on the CIP priorities of the incoming and leaving groups.' },
  { id: 'og1-010', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'E2 requires the β-H and leaving group to be…', opts: ['cis to each other', 'gauche, about 60°', 'anti-periplanar', 'geminal, on one carbon'], a: 2, why: 'Concerted TS needs aligned orbitals at 180°. On cyclohexanes: both must be AXIAL.' },
  { id: 'og1-011', topic: 'organic1', skill: 'organic/stereochemistry', q: 'A molecule with 3 stereocenters has at most how many stereoisomers?', opts: ['3', '8', '6', '9'], a: 1, why: '2ⁿ = 2³ = 8 — fewer if meso forms exist (internal mirror symmetry).' },
  { id: 'og1-012', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Best leaving group?', opts: ['I⁻', 'HO⁻', 'F⁻', 'H⁻'], a: 0, why: 'Leaving ability tracks weak basicity: I⁻ > Br⁻ > Cl⁻ ≫ F⁻. HO⁻ and H⁻ are terrible (strong bases) — protonate OH first!', misconception: 'Leaving-group ability tracks <em>weak basicity</em>, i.e. the stability of the anion once it has left. I⁻ is the best of the halides and F⁻ the worst — the reverse of electronegativity-based intuition — and HO⁻ and H⁻ are so basic that they essentially never leave. This is why alcohols are protonated (or tosylated) before substitution: you must convert OH into something that is willing to go.' },
  { id: 'og1-013', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'SN2 is fastest in polar APROTIC solvents (DMSO, acetone) because…', opts: ['they dissolve far more of the substrate', 'they are cheaper and easier to dry', 'they stabilise the carbocation formed', 'they leave the nucleophile bare'], a: 3, why: 'Protic solvents H-bond and cage the nucleophile. Aprotic solvents solvate only the cation, leaving the anion hot.' },
  { id: 'og1-014', topic: 'organic1', skill: 'organic/substitution-elimination', q: '2-bromobutane + NaOEt gives mainly…', opts: ['1-butene, the Hofmann product', 'butane, by reduction', '2-butene, the Zaitsev product', '2-butanol, by substitution'], a: 2, why: 'Small strong base → E2 toward the MORE substituted (more stable) alkene: Zaitsev\'s rule. And trans > cis within that.', misconception: 'Which alkene forms is decided by the <em>base</em>, not by the substrate alone. A small strong base (NaOEt) removes the most accessible proton that gives the most substituted, most stable alkene — Zaitsev. A bulky base (KOtBu) cannot reach that hydrogen and takes a terminal one instead, giving the LESS substituted Hofmann product. Quoting Zaitsev as a universal rule misses half the exam questions on elimination.' },
  { id: 'og1-015', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Same substrate with bulky KOtBu gives mainly…', opts: ['2-butene, the Zaitsev product', '1-butene, the Hofmann product', 'the ether, by substitution', 'no reaction at all'], a: 1, why: 'The fat base can only reach the exposed terminal CH₃ hydrogens → LESS substituted alkene. Base size flips regiochemistry.' },
  { id: 'og1-016', tier: 3, topic: 'organic1', skill: 'organic/mechanisms', q: 'The 2° cation from 3-methyl-2-butanol under acid rearranges by…', opts: ['a hydride shift to 3°', 'a methyl shift down to 1°', 'closing onto a ring', 'no rearrangement at all'], a: 0, why: 'The adjacent C–H slides over: 2° → 3° cation is downhill. Expect "wrong" SN1/E1 products whenever this is possible.', misconception: 'Carbocations rearrange whenever a hydride or alkyl shift can reach a more stable cation, and they do it faster than most nucleophiles arrive. A secondary cation next to a tertiary carbon will not wait around to be captured — it becomes tertiary first, and the product comes from <em>there</em>. Any SN1 or E1 answer drawn without checking for a possible shift is a likely wrong product.' },
  { id: 'og1-017', topic: 'organic1', skill: 'organic/stereochemistry', q: 'A meso compound is…', opts: ['chiral, with two stereocentres', 'always optically active in solution', 'a 50:50 mixture of enantiomers', 'achiral despite stereocentres'], a: 3, why: 'An internal mirror plane makes the molecule superimposable on its reflection — e.g. (2R,3S)-tartaric acid. Reduces the 2ⁿ count.' },
  { id: 'og1-018', tier: 3, topic: 'organic1', skill: 'organic/stereochemistry', q: 'Assigning R/S with the LOWEST priority group pointing at you: trace 1→2→3 clockwise reads…', opts: ['R', 'cannot assign', 'S', 'E'], a: 2, why: 'Viewing from the wrong side — REVERSE the call: clockwise reads R but the answer is S.', misconception: 'The 1 → 2 → 3 rotation only reads directly when the LOWEST priority points away from you. With it pointing at you, you are looking at the molecule from behind and the sense you see is inverted, so a clockwise trace is S. Reporting the rotation you traced without first checking where group 4 points is the commonest R/S error there is.' },
  { id: 'og1-019', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'In methanol (protic), the better nucleophile is…', opts: ['F⁻', 'I⁻', 'equal', 'neither reacts'], a: 1, why: 'Protic solvent grips small hard F⁻ in an H-bond cage; big polarizable I⁻ slips free. In DMSO the order flips!', misconception: 'Nucleophilicity is solvent-dependent, and the order can invert completely. In a protic solvent like methanol, small hard F⁻ is locked in a hydrogen-bonded cage while big polarisable I⁻ is barely solvated, so I⁻ is the better nucleophile. In a polar aprotic solvent like DMSO, which solvates only cations, the anions are all left bare and the order reverses to F⁻ &gt; I⁻. "Iodide is always the better nucleophile" is only half the story.' , why2: 'Nucleophilicity in solution is a <em>difference</em>: how much the ion wants the carbon, minus how much the solvent refuses to let go of it. Methanol has an O–H to donate, and it hydrogen-bonds hard to small, charge-dense F⁻ — that cage has to be stripped off before any attack can happen, and the cost exceeds what F⁻ gains from being the stronger base. I⁻ is big and its charge is smeared thin, so methanol barely holds it and it walks in. The clean test of this model is to remove the cage: in DMSO (aprotic — no O–H to donate) nothing is solvated that way, the penalty vanishes, and the order snaps back to basicity, F⁻ &gt; Cl⁻ &gt; Br⁻ &gt; I⁻. Any explanation that does not predict that reversal is not explaining the right thing.' },
  { id: 'og1-020', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Benzylic halides are unusually fast in…', opts: ['SN1 only, via the cation', 'BOTH SN1 and SN2', 'SN2 only, being unhindered', 'neither, being too hindered'], a: 1, why: 'Resonance stabilizes the cation (SN1) AND the SN2 transition state. Same for allylic.' },
  { id: 'og1-021', topic: 'organic1', skill: 'organic/substitution-elimination', q: 'Vinyl and aryl halides undergo SN1/SN2…', opts: ['rapidly, by either route', 'only when strongly heated', 'essentially never, by either route', 'only with concentrated NaOH, by backside attack at the sp² carbon'], a: 2, why: 'sp² C–X is short and strong, backside approach is blocked by the π system, and the cations are terrible. (Different chemistry — elimination/metal catalysis — is needed.)' },
  { id: 'og1-022', topic: 'organic1', q: 'CF₃COOH (pKa 0.2) is ~40,000× stronger than CH₃COOH (4.8) because…', opts: ['it is simply the heavier molecule', 'it carries more acidic protons', 'the F lone pairs delocalise by resonance', 'three F withdraw density inductively'], a: 3, why: 'Induction through σ bonds — the effect fades sharply with distance (β-F helps far less).' },
  { id: 'og1-023', topic: 'organic1', q: 'To deprotonate a terminal alkyne (pKa 25), use…', opts: ['NaNH₂, pKa 38', 'NaOH, pKa 15.7', 'NaHCO₃, pKa 6.4', 'NaCl, a neutral salt'], a: 0, why: 'You need the conjugate base of a WEAKER acid (higher pKa). NH₂⁻ (38 > 25) works; HO⁻ (15.7 < 25) fails — equilibrium lies wrong.', misconception: 'Acid–base reactions only run in the direction that makes the <em>weaker</em> acid, so you have to compare pKa values before choosing a base. Deprotonating a terminal alkyne (pKa 25) needs the conjugate base of a weaker acid — NaNH₂ works (NH₃, pKa 38) while NaOH does not (water, 15.7), and the hydroxide equilibrium sits about 10⁹ in the wrong direction. Picking a base by how "strong" it sounds, rather than by the pKa gap, is the mistake.' },
  { id: 'og1-024', topic: 'organic1', skill: 'organic/stereochemistry', q: 'Enantiomers differ in…', opts: ['their boiling points', 'optical rotation direction', 'their solubility in ethanol', 'their molar masses'], a: 1, why: 'Identical in every scalar property; they differ only toward chiral probes: plane-polarized light, chiral reagents, enzymes.', misconception: 'Enantiomers are identical in every ordinary physical property: same boiling point, same solubility, same NMR spectrum, same molar mass. They differ only in the presence of something else that is chiral — plane-polarised light, a chiral catalyst, an enzyme, a receptor. This is why separating them needs a chiral environment and why one enantiomer of a drug can be therapeutic while the other is inert or harmful.' },
  { id: 'og1-025', tier: 3, topic: 'organic1', skill: 'organic/substitution-elimination', q: 'cis-1-bromo-4-tert-butylcyclohexane does E2 faster than trans because…', opts: ['the trans isomer is the more strained of the two', 'the trans isomer has no β-hydrogen', 'in cis, Br can sit AXIAL as E2 needs', 'bromine is effectively bigger in trans'], a: 2, why: 't-Bu demands equatorial; in the cis isomer Br is then axial — exactly what anti-periplanar E2 needs. In trans, Br is stuck equatorial → very slow.', misconception: 'E2 needs the leaving group ANTI-PERIPLANAR to a β-hydrogen, which on a cyclohexane ring means both must be axial — the rate difference is about orbital alignment, not sterics or strain. The bulky t-Bu group is locked equatorial, which forces Br axial in the cis isomer and traps it equatorial in the trans one; explanations like "trans is more strained" or "Br is effectively bigger" answer a sterics question that was never asked.' },
];

export const ORGANIC2_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'og2-001', topic: 'organic2', skill: 'organic/aromatic', q: 'The molecular formula of benzene is…', opts: ['C₆H₁₂', 'C₆H₆', 'C₆H₁₀', 'C₆H₅'], a: 1, why: 'Planar aromatic ring, 6 π electrons (4n+2, n=1).' },
  { id: 'og2-002', topic: 'organic2', skill: 'organic/mechanisms', q: 'Markovnikov\'s rule: in HX addition, H goes to the carbon…', opts: ['with more H\'s already', 'with fewer H\'s', 'that is most substituted', 'bonded to X'], a: 0, why: '"The rich get richer" — this places the + charge on the MORE substituted (more stable) carbon.', misconception: 'Markovnikov is a statement about carbocation stability, not a rule about where hydrogen "likes" to go. The proton adds so as to leave the positive charge on the more substituted carbon, because that cation is the more stable one. Memorising "H goes to the carbon with more H" gets the right answer for HX and then fails you on hydroboration, where sterics rather than a cation decide, and on radical HBr addition, where a radical does.' },
  { id: 'og2-003', topic: 'organic2', q: 'Adding H₂/Pd to an alkene gives…', opts: ['an alkyne', 'a ketone', 'an alcohol', 'an alkane'], a: 3, why: 'Catalytic hydrogenation saturates the C=C (syn addition on the metal surface).' },
  { id: 'og2-004', topic: 'organic2', skill: 'organic/carbonyl', q: 'Full oxidation of a primary alcohol gives…', opts: ['a ketone, then no further', 'an ester with itself', 'a carboxylic acid', 'an alkene, by dehydration'], a: 2, why: '1° alcohol → aldehyde → carboxylic acid (with Jones/KMnO₄; PCC stops at aldehyde).' },
  { id: 'og2-005', topic: 'organic2', skill: 'organic/carbonyl', q: 'An ester is made from…', opts: ['two alcohols condensing', 'an acid and an alcohol', 'two acids, losing water', 'an amine plus an alcohol'], a: 1, why: 'Fischer esterification: RCOOH + R′OH ⇌ RCOOR′ + H₂O (acid-catalyzed).' },
  // ---- olympiad ----
  { id: 'og2-006', topic: 'organic2', skill: 'organic/mechanisms', q: 'Propene + HBr (no peroxides) gives mainly…', opts: ['2-bromopropane', '1-bromopropane', '1,2-dibromopropane', 'propane'], a: 0, why: 'Markovnikov via the 2° carbocation. Peroxides flip it to 1-bromopropane (radical, anti-Markovnikov).' },
  { id: 'og2-007', topic: 'organic2', skill: 'organic/aromatic', q: 'Nitration of toluene gives mostly…', opts: ['meta, chiefly', 'no reaction under these conditions', 'ipso, replacing CH₃', 'ortho and para'], a: 3, why: '–CH₃ is a weak activator and o/p director (hyperconjugation stabilizes the o/p arenium ions).' },
  { id: 'og2-008', topic: 'organic2', skill: 'organic/aromatic', q: '–NO₂ on a benzene ring is…', opts: ['an activator directing o/p', 'a deactivator directing o/p', 'deactivator, meta', 'an activator directing meta'], a: 2, why: 'π-withdrawal destabilizes o/p attack worst (positive charge lands beside NO₂) → meta survives, everything slower.', misconception: 'Activating/deactivating and ortho-para/meta directing are two separate questions, and only one of them is settled by the resonance arrow. NO₂ withdraws by both induction and resonance, so it deactivates the ring <em>and</em> directs meta — but the halogens deactivate (induction) while directing ortho/para (their lone pairs stabilise those intermediates). Assuming "deactivator ⇒ meta director" gets every halogen wrong.' },
  { id: 'og2-009', topic: 'organic2', skill: 'organic/carbonyl', q: 'A ketone + NaBH₄ gives…', opts: ['1° alcohol', '2° alcohol', 'carboxylic acid', 'alkane'], a: 1, why: 'Hydride to the carbonyl carbon: R₂C=O → R₂CH–OH. Aldehydes give 1° alcohols.' },
  { id: 'og2-010', topic: 'organic2', q: 'Point group of H₂O?', opts: ['C₂', 'Cₛ', 'D₂ₕ', 'C₂ᵥ'], a: 3, why: 'One C₂ axis + two σᵥ planes containing it.' },
  { id: 'og2-011', topic: 'organic2', skill: 'organic/stereochemistry', q: 'Which molecule is CHIRAL?', opts: ['gauche H₂O₂', 'XeF₄', 'trans-dichloroethene', 'CH₂Cl₂'], a: 0, why: 'Gauche H₂O₂ has ONLY a C₂ rotation — no σ, i, or Sₙ. Pure rotations don\'t kill chirality.' },
  { id: 'og2-012', topic: 'organic2', skill: 'organic/mechanisms', q: 'Hydroboration–oxidation (BH₃, then H₂O₂/OH⁻) of propene gives…', opts: ['propan-2-ol', 'propan-1-ol', 'propanal', 'propanoic acid'], a: 1, why: 'Anti-Markovnikov and syn: boron (the future OH) adds to the LESS hindered carbon — sterics, not cations.', misconception: 'Hydroboration–oxidation puts the OH on the LESS substituted carbon, and no carbocation is involved anywhere. Boron and hydrogen add across the double bond in one concerted, syn step, with boron going to the less hindered end for steric reasons — then H₂O₂/OH⁻ replaces B with OH, retaining that position and that stereochemistry. Calling this "anti-Markovnikov because the cation is different" invents a mechanism that does not exist.' },
  { id: 'og2-013', tier: 3, topic: 'organic2', q: 'Ozonolysis of an alkene (O₃, then Zn/H₂O) gives 2 equivalents of acetone. The alkene was…', opts: ['2-butene, but-2-ene', 'propene, CH₃CH=CH₂', '2,3-dimethylbut-2-ene', 'isobutylene, 2-methylpropene'], a: 2, why: 'Rebuild by gluing the carbonyls: (CH₃)₂C=O + O=C(CH₃)₂ → (CH₃)₂C=C(CH₃)₂. Ozonolysis is a structure-determination scalpel.', misconception: 'Rebuilding an ozonolysis substrate means gluing the two carbonyl CARBONS together with a double bond — the oxygens are cleaved away, not carried into the alkene. Two acetone fragments therefore demand (CH₃)₂C= on both sides; isobutylene would give one acetone and one formaldehyde, and but-2-ene would give two acetaldehydes, not two acetones.' },
  { id: 'og2-014', topic: 'organic2', skill: 'organic/mechanisms', q: 'Br₂ addition to cyclohexene gives…', opts: ['cis-1,2-dibromocyclohexane, meso', '1,1-dibromocyclohexane, geminal', 'bromobenzene, by substitution', 'trans-1,2-dibromocyclohexane'], a: 3, why: 'The bromonium ion forces backside attack → ANTI addition → trans product (both enantiomers).', misconception: 'Br₂ adds ANTI, not syn, and the reason is the bridged bromonium ion. The first bromine forms a three-membered ring across the alkene face, and bromide has to attack from the opposite side, so the two bromines end up trans. Drawing both bromines adding to the same face is the intuitive answer and gives the wrong diastereomer.' },
  { id: 'og2-015', tier: 3, topic: 'organic2', skill: 'organic/aromatic', q: 'Friedel–Crafts ALKYLATION with 1-chloropropane/AlCl₃ gives mostly…', opts: ['isopropylbenzene', 'n-propylbenzene, unrearranged', 'toluene, by C–C cleavage', 'no reaction with a 1° halide'], a: 0, why: 'The 1° cation-like complex rearranges (hydride shift) to 2° before attacking. FC ACYLATION avoids this — acylium doesn\'t rearrange.', misconception: 'Friedel–Crafts alkylation is unreliable exactly because the electrophile rearranges. A primary alkyl halide generates a cation-like complex that shifts a hydride to become secondary before it ever reaches the ring, so 1-chloropropane gives cumene, not n-propylbenzene. Acylation avoids this — the acylium ion is resonance-stabilised and does not rearrange — which is why the standard route to a straight-chain alkyl group is acylate first, then reduce.' , why2: 'Draw the electrophile and ask whether it has somewhere better to be. The 1-chloropropane/AlCl₃ complex is essentially a primary cation, CH₃CH₂CH₂⁺ — and a hydride sitting on the adjacent carbon can slide over to give the secondary cation, a large drop in energy. Benzene is a <em>weak</em> nucleophile and slow to attack, so the rearrangement wins the race and the ring meets the isopropyl cation, giving cumene. Working rule: in Friedel–Crafts alkylation, if the cation can rearrange, assume it has. The industrial answer to this is the reason acylation exists — an acylium R–C≡O⁺ is resonance-stabilised with a complete octet at carbon and has nothing to gain by shifting, so acylate first and reduce the ketone afterwards (Clemmensen or Wolff–Kishner) to get the straight chain.' },
  { id: 'og2-016', topic: 'organic2', skill: 'organic/aromatic', q: 'Friedel–Crafts reactions FAIL on…', opts: ['toluene, being activated', 'nitrobenzene', 'anisole, strongly activated', 'benzene itself'], a: 1, why: 'Strongly deactivated rings can\'t stabilize the arenium ion. (They also fail on anilines — AlCl₃ grabs the N lone pair.)' },
  { id: 'og2-017', topic: 'organic2', skill: 'organic/aromatic', q: 'Bromination of aniline WITHOUT protection gives…', opts: ['the mono-para product only', 'the meta product predominantly', '2,4,6-tribromoaniline', 'no reaction without a catalyst'], a: 2, why: '–NH₂ is so activating that bromine water tribrominates on contact. Protect as the amide (acetanilide) to stop at mono.' },
  { id: 'og2-018', tier: 3, topic: 'organic2', skill: 'organic/carbonyl', q: 'The aldol product of two acetaldehyde molecules is…', opts: ['ethyl acetate', 'butanal', 'crotonaldehyde only', '3-hydroxybutanal'], a: 3, why: 'Enolate of one attacks the carbonyl of the other → β-hydroxy aldehyde (3-hydroxybutanal); heat dehydrates it to crotonaldehyde (E1cb).', misconception: 'Aldol ADDITION and aldol CONDENSATION are two stages, and the question stops at the first: the enolate attacks a carbonyl to give the β-hydroxy aldehyde, and crotonaldehyde only appears once that alcohol is dehydrated, which takes heat or forcing base. Naming crotonaldehyde treats the condensation as automatic, while butanal has no OH at all and could not come from adding one carbonyl compound to another.' },
  { id: 'og2-019', topic: 'organic2', skill: 'organic/carbonyl', q: 'Acetals protect ketones because they are stable to…', opts: ['base and nucleophiles', 'aqueous acid on warming', 'essentially every reagent', 'oxidising conditions only'], a: 0, why: 'Acetals ignore bases, Grignards, hydrides — then mild aqueous acid unzips them back to the ketone. Orthogonal protection.' },
  { id: 'og2-020', tier: 3, topic: 'organic2', skill: 'organic/carbonyl', q: 'Ester + 2 CH₃MgBr gives, after workup…', opts: ['a 3° alcohol, two CH₃ added', 'a ketone, stopping at one addition', 'the carboxylic acid, on workup', 'an ether from the alkoxide'], a: 0, why: 'The intermediate ketone is MORE reactive than the ester — the second equivalent attacks before you can stop it.', misconception: 'Grignard reagents cannot be stopped at the ketone stage when they attack an ester, because the ketone they produce is <em>more</em> electrophilic than the ester they came from. The second equivalent adds immediately, giving a tertiary alcohol with two identical new groups. Stopping at the ketone requires a deliberately damped reagent (a Weinreb amide, or a Gilman cuprate).' },
  { id: 'og2-021', topic: 'organic2', skill: 'organic/carbonyl', q: 'Tollens\' reagent (Ag(NH₃)₂⁺) distinguishes…', opts: ['alkenes from alkanes', '1° from 2° alcohols directly', 'carboxylic acids from esters', 'aldehydes from ketones'], a: 3, why: 'Aldehydes reduce Ag⁺ to a silver mirror; ketones don\'t. Fehling\'s (Cu²⁺ → red Cu₂O) does the same job.' },
  { id: 'og2-022', topic: 'organic2', skill: 'organic/carbonyl', q: 'Reactivity order of carboxylic acid derivatives toward nucleophiles?', opts: ['amide > ester > anhydride > acid chloride', 'ester > acid chloride > amide', 'acid chloride > anhydride > ester > amide', 'all four react at the same rate'], a: 2, why: 'Better leaving group + less resonance donation = more reactive. Amides are the most stable — that\'s why proteins survive.', misconception: 'Carboxylic acid derivative reactivity follows leaving-group ability and resonance donation together: acid chloride &gt; anhydride &gt; ester &gt; amide. The amide is least reactive because nitrogen donates its lone pair into the carbonyl most effectively and NH₂⁻ is a hopeless leaving group — which is precisely why the peptide bonds holding proteins together survive in water. Ranking by "which looks most reactive" without the leaving group in mind inverts the series.' },
  { id: 'og2-023', topic: 'organic2', skill: 'organic/carbonyl', q: 'To form an enolate quantitatively (not an equilibrium), deprotonate a ketone (pKa ~20) with…', opts: ['NaOEt (pKa 16)', 'LDA (pKa ~36)', 'NaHCO₃', 'H₂O'], a: 1, why: 'LDA\'s conjugate acid is 10¹⁶ weaker → complete, fast, and too bulky to attack the carbonyl itself. NaOEt gives only ~10⁻⁴ enolate.' },
  { id: 'og2-024', topic: 'organic2', q: 'Which molecule has an inversion center i?', opts: ['trans-dichloroethene', 'cis-dichloroethene, C₂ᵥ', 'NH₃, pyramidal', 'CHFClBr, fully asymmetric'], a: 0, why: 'Trans: every atom maps through the center onto its twin → C₂ₕ, zero dipole. Cis (C₂ᵥ) has a dipole — tell them apart by polarity!' },
  { id: 'og2-025', topic: 'organic2', skill: 'organic/stereochemistry', q: 'A molecule is guaranteed ACHIRAL if it has…', opts: ['a C₂ rotation axis', 'delocalised resonance', 'more than four atoms in it', 'any improper operation'], a: 3, why: 'Chirality test: no mirror, no inversion, no rotation-reflection. Proper rotations alone (like C₂ in H₂O₂) leave it chiral.', misconception: 'The test for chirality is the absence of any <em>improper</em> symmetry operation — a mirror plane, an inversion centre, or an improper rotation Sₙ. Proper rotation axes do not disqualify a molecule: gauche H₂O₂ has a C₂ axis and is still chiral. Looking only for "an internal mirror plane" is nearly right and misses the Sₙ cases that olympiad questions are built on.' },
];

export const LABDATA_QUIZ: QuizQ[] = [
  // ---- warm-ups ----
  { id: 'lbd-001', topic: 'labdata', skill: 'lab/measurement', q: 'Read a buret at the…', opts: ['top of the meniscus', 'highest graduation', 'side of the tube', 'bottom of the meniscus, at eye level'], a: 3, why: 'Bottom of the curved meniscus, eye level to kill parallax.' },
  { id: 'lbd-002', topic: 'labdata', skill: 'lab/sig-figs', q: '12.5 + 1.25 = ? (correct sig figs)', opts: ['13.75', '14', '13.8', '13.7'], a: 2, why: 'Addition keeps the fewest DECIMAL PLACES: 12.5 has one → 13.8.' },
  { id: 'lbd-003', topic: 'labdata', q: 'λmax is the wavelength where the sample…', opts: ['transmits most', 'absorbs most', 'reflects most', 'fluoresces'], a: 1, why: 'Peak of the absorption spectrum — measure there for best sensitivity.' },
  { id: 'lbd-004', topic: 'labdata', skill: 'lab/error-analysis', q: 'Precision means the measurements are…', opts: ['reproducible/close to each other', 'close to the true value', 'recorded quickly', 'in SI units'], a: 0, why: 'Precision = spread (random error); accuracy = closeness to truth (systematic error).' },
  { id: 'lbd-005', topic: 'labdata', q: 'Beer\'s law says absorbance is proportional to…', opts: ['1/concentration', 'temperature', 'concentration²', 'concentration'], a: 3, why: 'A = εbc — double the concentration, double the absorbance (in the linear range).' },
  // ---- olympiad ----
  { id: 'lbd-006', tier: 3, topic: 'labdata', skill: 'lab/titration-technique', q: 'Your Erlenmeyer flask is wet with distilled water before adding the acid aliquot. The measured concentration will be…', opts: ['too high', 'too low', 'unaffected', 'unpredictable'], a: 2, why: 'MOLES of acid are unchanged — extra water dilutes the flask but not the amount the titrant must neutralize. The most-tested titration fact.', misconception: 'Water in the titration flask changes the concentration but not the number of <em>moles</em> of analyte, and it is moles the titrant reacts with. So a wet flask has no effect on the result — while a wet buret or pipet, which changes the amount actually delivered, does. Sorting "affects moles" from "affects concentration only" is the entire skill this class of question tests.' , why2: 'Look at which volume appears in the calculation. You compute c(acid) = c(base)·V(base)/V(acid), and V(acid) is the volume you <em>pipetted</em>, not the volume standing in the flask. The rinse water dilutes what is in the flask but changes neither the moles of acid delivered nor the moles of titrant needed to reach the endpoint, so every number in that formula is untouched. The contrast is what makes the fact stick: the pipet and the buret <em>deliver</em>, so water clinging to them dilutes a delivered amount and does change the result — rinse each with the solution it will hold. The conical flask only <em>contains</em>, so distilled water in it is harmless.' },
  { id: 'lbd-007', topic: 'labdata', skill: 'lab/sig-figs', q: 'How many sig figs in 0.020?', opts: ['1', '2', '3', '4'], a: 1, why: 'Leading zeros never count; the trailing zero does (decimal point present) → 2.' },
  { id: 'lbd-008', topic: 'labdata', skill: 'lab/measurement', q: 'A buret is read to the nearest…', opts: ['0.01 mL', '0.1 mL', '1 mL', '0.001 mL'], a: 0, why: 'Graduated every 0.1 mL; you estimate one more digit → 24.37 mL.' },
  { id: 'lbd-009', topic: 'labdata', q: 'A = 1.0 means transmittance = …', opts: ['90%', '50%', '1%', '10%'], a: 3, why: 'A = −log T → T = 10%. Above A ≈ 1 the signal is noise-dominated: dilute and re-measure.' },
  { id: 'lbd-010', topic: 'labdata', skill: 'lab/error-analysis', q: 'Five replicates cluster tightly, all 5% above the true value. The data are…', opts: ['accurate and precise', 'precise but not accurate', 'accurate but not precise', 'neither'], a: 1, why: 'Tight = precise; consistent offset = SYSTEMATIC error (e.g., miscalibrated balance). More trials won\'t fix it.', misconception: 'Precision and accuracy fail independently, and only one of them can be fixed by repeating the experiment. Five tightly clustered readings all 5% high are precise and inaccurate: the scatter is small, but a systematic bias — a miscalibrated balance, an uncorrected blank — shifts every one of them the same way. Averaging more trials will report that bias with more confidence, not remove it.' },
  { id: 'lbd-011', topic: 'labdata', skill: 'lab/sig-figs', q: 'Sig figs in 6.022×10²³?', opts: ['3', '23', '4', '27'], a: 2, why: 'Count the mantissa digits only: 6, 0, 2, 2 → 4. The exponent is exact bookkeeping.' },
  { id: 'lbd-012', topic: 'labdata', skill: 'lab/sig-figs', q: '2.5 × 3.42 = ? (correct sig figs)', opts: ['8.55', '9', '8.5', '8.6'], a: 3, why: 'Multiplication keeps the FEWEST sig figs (2.5 has two) → 8.6.' },
  { id: 'lbd-013', topic: 'labdata', q: 'The blank cuvette (solvent only) is measured to…', opts: ['zero out absorption by solvent and cell', 'clean the instrument', 'calibrate the wavelength', 'warm up the lamp'], a: 0, why: 'Subtracting the blank isolates the analyte\'s absorbance from background — a systematic-error correction.' },
  { id: 'lbd-014', topic: 'labdata', skill: 'lab/measurement', q: 'To deliver exactly 25.00 mL, use a…', opts: ['graduated cylinder', 'volumetric pipet', 'beaker', 'Erlenmeyer flask'], a: 1, why: 'Volumetric pipet: ±0.03 mL. Graduated cylinder ±0.5; beaker markings are decoration (±5%).' },
  { id: 'lbd-015', topic: 'labdata', skill: 'lab/error-analysis', q: 'Averaging many trials reduces…', opts: ['systematic error', 'both equally', 'random error', 'neither'], a: 2, why: 'Random scatter cancels with √N; a systematic bias just gets averaged INTO the result. Identify bias with a standard, not statistics.', misconception: 'Averaging attacks random error only, shrinking the standard error as 1/√N. A systematic error survives averaging untouched, because every measurement carries it identically. The way to find a bias is a standard, a blank or a second method — never more replicates of the same flawed procedure.' },
  { id: 'lbd-016', topic: 'labdata', q: '%T = 25%. Absorbance = ?', opts: ['0.25', '0.40', '0.75', '0.60'], a: 3, why: 'A = −log(0.25) = log 4 ≈ 0.60.' },
  { id: 'lbd-017', topic: 'labdata', q: 'A calibration line has a distinctly nonzero intercept. Best response?', opts: ['suspect a blank/systematic offset and subtract or investigate it', 'force it through zero', 'ignore it', 'discard the data'], a: 0, why: 'An offset usually means uncorrected background (dirty cuvette, blank error). Use the fitted line (with intercept) to read unknowns.', misconception: 'A calibration line with a clearly nonzero intercept is telling you something, and forcing it through the origin throws the information away. The usual cause is an uncorrected background — a dirty cuvette, a blank that was not subtracted — and the correct response is to investigate it and then read unknowns off the fitted line, intercept included. Beer\'s law predicts A = 0 at c = 0; if your data disagree, the data are describing your apparatus.' },
  { id: 'lbd-018', topic: 'labdata', q: 'A colored solution is diluted 1:1 with water. Its absorbance…', opts: ['doubles', 'halves', 'is unchanged', 'goes to zero'], a: 1, why: 'A ∝ c: half the concentration, half the absorbance. Handy check that you\'re inside the linear range.' },
  { id: 'lbd-019', tier: 3, topic: 'labdata', skill: 'lab/titration-technique', q: 'An air bubble in the buret tip escapes DURING the titration. The reported concentration of analyte is…', opts: ['unaffected', 'too low', 'too high', 'random'], a: 2, why: 'The bubble\'s volume counts as delivered titrant that never was → V reads high → calculated moles of analyte high. Always trace error direction through the formula.', misconception: 'Trace the error through the formula instead of guessing its direction. The bubble\'s volume is recorded as titrant delivered but carried no titrant, so the buret READING is too large and moles of analyte = M × V come out too large with it. Arguing "less titrant actually reacted, so the result must be low" confuses what was delivered with what was read — the calculation only ever sees the reading.' },
  { id: 'lbd-020', topic: 'labdata', skill: 'lab/measurement', q: 'The best way to weigh a hygroscopic solid:', opts: ['slowly, in open air', 'after wetting it', 'by difference, quickly, in a closed container', 'on filter paper'], a: 2, why: 'Weigh (container + sample), pour, re-weigh container: drift and residue cancel; speed and closure limit water uptake.' },
  { id: 'lbd-021', tier: 3, topic: 'labdata', skill: 'lab/sig-figs', q: 'pH of 0.0025 M HCl (2 sig figs), reported correctly:', opts: ['2.6', '2.60', '2.602', '3'], a: 1, why: 'Log rule: sig figs of the number → DECIMAL PLACES of the log. 2 sf → pH = 2.60 (the "2" before the point just marks the power of ten).', misconception: 'For a logarithm, the significant figures of the number become the DECIMAL PLACES of the log. 0.0025 M has two significant figures, so the pH is 2.60 — the "2" before the point only records the power of ten and is not a significant figure at all. Reporting pH 2.6 loses a digit you measured; reporting 2.602 claims one you did not.' },
  { id: 'lbd-022', topic: 'labdata', q: 'Two serial 1:10 dilutions give a total dilution of…', opts: ['1:100', '1:20', '1:10', '1:1000'], a: 0, why: 'Dilution factors multiply: 10 × 10 = 100. Serial dilution beats one huge dilution for accuracy.' },
  { id: 'lbd-023', topic: 'labdata', skill: 'lab/titration-technique', q: 'Before titrating, rinse the PIPET with ______ and the FLASK with ______.', opts: ['water / water', 'acetone / air', 'titrant / titrant', 'the analyte solution / distilled water'], a: 3, why: 'Pipet residue must be the solution it measures (water would dilute it). Flask water doesn\'t matter — moles are already fixed.', misconception: 'The rinse rule follows from whether the vessel\'s contents affect moles delivered. A pipet or buret must be rinsed with the solution it will dispense, because leftover water would dilute what it measures out. The titration flask is rinsed with distilled water only — extra water there changes the concentration but not the moles waiting to react, so it cannot change the result.' },
  { id: 'lbd-024', tier: 3, topic: 'labdata', skill: 'lab/error-analysis', q: 'Each buret reading is ±0.02 mL. The delivered volume (difference of two readings) is uncertain by about…', opts: ['±0.01 mL', '±0.02 mL', '±0.04 mL', '±0.4 mL'], a: 2, why: 'Absolute uncertainties ADD for subtraction: 0.02 + 0.02 = ±0.04 mL. (In quadrature √2×0.02 ≈ 0.03 — either answer beats ±0.02.)', misconception: 'Uncertainties do not cancel when you subtract; they accumulate. A delivered volume is the difference between two buret readings, each ±0.02 mL, so the result is uncertain by ±0.04 mL (or ±0.03 combined in quadrature) — never the ±0.02 of a single reading. Any quantity computed from a <em>difference</em> is less certain than its inputs, which is why titrating to a small volume difference is bad practice.' },
  { id: 'lbd-025', topic: 'labdata', q: 'Measuring at a steep shoulder of the absorption band instead of λmax causes…', opts: ['better accuracy', 'high sensitivity to tiny wavelength drift', 'no difference', 'negative absorbance'], a: 1, why: 'On a slope, a 1–2 nm drift changes ε a lot; at the flat peak it barely matters. λmax = max sensitivity AND max robustness.' },
];
